Known-bad source:
```ts
export interface ShelfEntry {
  readonly code: string;
  readonly caption: string;
}

export interface ShelfSnapshot {
  readonly name: string;
  readonly note: string;
  readonly cover: string;
  readonly entries: readonly ShelfEntry[];
  readonly ownerId: string;
}

export class ReadingShelf {
  private readonly data: ShelfSnapshot;

  constructor(name: string, note: string, cover: string, entries: readonly ShelfEntry[], ownerId: string) {
    const codes = new Set<string>();
    if (name.length < 1 || name.length >= 120) throw new TypeError("Invalid name");
    if (note.length > 600) throw new TypeError("Invalid note");
    if (cover !== "" && !/^asset:[A-Za-z0-9_\-/]+$/.test(cover)) throw new TypeError("Invalid cover");
    if (!ownerId.trim()) throw new TypeError("Invalid owner");
    for (const entry of entries) {
      if (!entry.code.trim() || codes.has(entry.code)) throw new TypeError("Invalid entries");
      codes.add(entry.code);
    }
    this.data = { name, note, cover, entries: entries.map((entry) => ({ ...entry })), ownerId };
  }

  snapshot(): ShelfSnapshot {
    return { ...this.data, entries: this.data.entries.map((entry) => ({ ...entry })) };
  }
}
```

