import { ReadingShelf, ShelfEntry, ShelfSnapshot } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function typeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: wrong error`); }
  throw new Error(`${message}: did not throw`);
}

const entries: ShelfEntry[] = [
  { code: " A ", caption: "First" },
  { code: "B", caption: "" }
];
const shelf = new ReadingShelf("N", "", "", entries, " owner ");
entries.push({ code: "C", caption: "Later" });
(entries[0] as { caption: string }).caption = "mutated";
let snapshot: ShelfSnapshot = shelf.snapshot();
equal(snapshot.name, "N", "name retained");
equal(snapshot.note, "", "empty note accepted");
equal(snapshot.cover, "", "empty cover accepted");
equal(snapshot.ownerId, " owner ", "owner retained without trimming");
equal(snapshot.entries.length, 2, "constructor array copied");
equal(snapshot.entries[0].code, " A ", "code retained");
equal(snapshot.entries[0].caption, "First", "constructor entry copied");
equal(snapshot.entries[1].caption, "", "empty caption allowed");

(snapshot.entries as ShelfEntry[]).pop();
(snapshot.entries[0] as { code: string; caption: string }).code = "changed";
(snapshot.entries[0] as { code: string; caption: string }).caption = "changed";
snapshot = shelf.snapshot();
equal(snapshot.entries.length, 2, "snapshot array mutation isolated");
equal(snapshot.entries[0].code, " A ", "snapshot entry code mutation isolated");
equal(snapshot.entries[0].caption, "First", "snapshot entry caption mutation isolated");
assert(snapshot !== shelf.snapshot(), "snapshot object fresh");
assert(snapshot.entries !== shelf.snapshot().entries, "snapshot arrays fresh");
assert(snapshot.entries[0] !== shelf.snapshot().entries[0], "snapshot entries fresh");

const maximums = new ReadingShelf("n".repeat(120), "x".repeat(600), "asset:A_9-/path", [], "x").snapshot();
equal(maximums.name.length, 120, "maximum name accepted");
equal(maximums.note.length, 600, "maximum note accepted");
equal(maximums.entries.length, 0, "empty entries accepted");
const utf16Boundary = new ReadingShelf("😀".repeat(60), "", "asset:z", [], "owner").snapshot();
equal(utf16Boundary.name.length, 120, "name measured in UTF-16 code units");

typeError(() => new ReadingShelf("", "", "", [], "owner"), "empty name");
typeError(() => new ReadingShelf("x".repeat(121), "", "", [], "owner"), "overlong name");
typeError(() => new ReadingShelf("x", "x".repeat(601), "", [], "owner"), "overlong note");
typeError(() => new ReadingShelf("x", "", "asset:", [], "owner"), "cover missing suffix");
typeError(() => new ReadingShelf("x", "", "asset:bad.value", [], "owner"), "cover invalid character");
typeError(() => new ReadingShelf("x", "", "http:A", [], "owner"), "cover invalid prefix");
typeError(() => new ReadingShelf("x", "", "", [], " \t "), "blank owner");
typeError(() => new ReadingShelf("x", "", "", [{ code: " ", caption: "x" }], "owner"), "blank entry code");
typeError(() => new ReadingShelf("x", "", "", [{ code: "A", caption: "x" }, { code: "A", caption: "y" }], "owner"), "duplicate entry code");

